            "solution": "<?php\ndeclare(strict_types=1);\n\nnamespace Acme\\Data\\Template;\n\nabstract class CsvProcessor\n{\n    /**\n     * Template method - final to enforce CSV processing skeleton.\n     */\n    final public function process(string $inputPath, string $outputPath): ProcessResult\n    {\n        $this->logProgress('Starting CSV processing');\n        $handle = $this->openFile($inputPath);\n\n        $headers = $this->parseHeaders($handle);\n        $rows = $this->parseRows($handle, $headers);\n\n        fclose($handle);\n        $this->logProgress(sprintf('Parsed %d rows', count($rows)));\n\n        $transformed = $this->transformData($rows);\n        $this->logProgress('Data transformation complete');\n\n        $outHandle = $this->writeOutput($outputPath, $transformed);\n        fclose($outHandle);\n\n        $this->logProgress('CSV processing completed');\n        return ProcessResult::successful(count($transformed));\n    }\n\n    /**\n     * Hook method - override for custom file opening.\n     */\n    protected function openFile(string $path)\n    {\n        $handle = fopen($path, 'r');\n        if ($handle === false) {\n            throw new \\RuntimeException(\"Cannot open file: $path\");\n        }\n        return $handle;\n    }\n\n    /**\n     * Hook method for progress logging.\n     */\n    protected function logProgress(string $message): void\n    {\n        // Default: no-op\n    }\n\n    /**\n     * Hook method for error handling.\n     */\n    protected function onError(string $message): void\n    {\n        throw new \\RuntimeException($message);\n    }\n\n    /**\n     * Hook method - override for custom file writing.\n     */\n    protected function writeOutput(string $path, array $data)\n    {\n        $handle = fopen($path, 'w');\n        if ($handle === false) {\n            throw new \\RuntimeException(\"Cannot write file: $path\");\n        }\n        foreach ($data as $row) {\n            fputcsv($handle, $row);\n        }\n        return $handle;\n    }\n\n    abstract protected function parseHeaders($handle): array;\n    abstract protected function parseRows($handle, array $headers): array;\n    abstract protected function transformData(array $rows): array;\n}\n\nclass UserImportProcessor extends CsvProcessor\n{\n    protected function parseHeaders($handle): array\n    {\n        $headers = fgetcsv($handle);\n        return $headers ?: [];\n    }\n\n    protected function parseRows($handle, array $headers): array\n    {\n        $rows = [];\n        while (($row = fgetcsv($handle)) !== false) {\n            $rows[] = array_combine($headers, $row);\n        }\n        return $rows;\n    }\n\n    protected function transformData(array $rows): array\n    {\n        return array_map(function ($row) {\n            $row['name'] = strtoupper($row['name'] ?? '');\n            $row['created_at'] = date('Y-m-d');\n            return $row;\n        }, $rows);\n    }\n}\n\nclass SalesExportProcessor extends CsvProcessor\n{\n    protected function parseHeaders($handle): array\n    {\n        $headers = fgetcsv($handle);\n      